import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor cute_conv2d(torch::Tensor input, torch::Tensor weight, torch::Tensor bias,
                           int64_t stride, int64_t padding);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

// Compile-time constants matching this specific Conv2d configuration.
#define KH 11
#define KW 11
#define STRIDE 4
#define PAD 2
#define C_IN 3
#define TILE 8
#define OC_TILE 16
#define IN_TILE ((TILE - 1) * STRIDE + KH)

__global__ void cute_conv2d_kernel(
    float const* __restrict__ input,
    float const* __restrict__ weight,
    float const* __restrict__ bias,
    float* __restrict__ output,
    int N, int H, int W,
    int C_out, int H_out, int W_out)
{
    // Global memory CuTe tensors (row-major / contiguous NCHW layouts)
    Tensor gInput = make_tensor(make_gmem_ptr(input),
        make_shape(N, C_IN, H, W),
        make_stride(C_IN * H * W, H * W, W, 1));
    Tensor gWeight = make_tensor(make_gmem_ptr(weight),
        make_shape(C_out, C_IN, KH, KW),
        make_stride(C_IN * KH * KW, KH * KW, KW, 1));
    Tensor gOutput = make_tensor(make_gmem_ptr(output),
        make_shape(N, C_out, H_out, W_out),
        make_stride(C_out * H_out * W_out, H_out * W_out, W_out, 1));
    constexpr int total_load = C_IN * IN_TILE * IN_TILE;
    constexpr int weight_tile_elems = OC_TILE * C_IN * KH * KW;
    // Single dynamic shared-memory allocation, partitioned into the input
    // halo tile and the double-buffered weight tile (same shapes/strides
    // as before, only the storage mechanism changed to fit within the
    // static 48KB shared memory limit).
    extern __shared__ float smem_raw[];
    float* sInput_ptr  = smem_raw;
    float* sWeight_ptr = smem_raw + total_load;
    Tensor sInput = make_tensor(make_smem_ptr(sInput_ptr),
        make_shape(Int<C_IN>{}, Int<IN_TILE>{}, Int<IN_TILE>{}),
        make_stride(Int<IN_TILE * IN_TILE>{}, Int<IN_TILE>{}, Int<1>{}));
    auto sWeight = [sWeight_ptr] (int buf, int idx) -> float& {
        return sWeight_ptr[buf * weight_tile_elems + idx];
    };
    int n      = blockIdx.z;
    int tile_w = blockIdx.x;
    int tile_h = blockIdx.y;
    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int tid = ty * TILE + tx;
    int num_threads = TILE * TILE;
    int ow0 = tile_w * TILE;
    int oh0 = tile_h * TILE;
    int iw0 = ow0 * STRIDE - PAD;
    int ih0 = oh0 * STRIDE - PAD;
    for (int idx = tid; idx < total_load; idx += num_threads) {
        int c   = idx / (IN_TILE * IN_TILE);
        int rem = idx % (IN_TILE * IN_TILE);
        int r   = rem / IN_TILE;
        int col = rem % IN_TILE;
        int ih = ih0 + r;
        int iw = iw0 + col;
        float val = 0.0f;
        if (ih >= 0 && ih < H && iw >= 0 && iw < W) {
            val = gInput(n, c, ih, iw);
        }
        sInput(c, r, col) = val;
    }
    __syncthreads();
    int oh = oh0 + ty;
    int ow = ow0 + tx;
    bool valid = (oh < H_out) && (ow < W_out);
    int base_h = ty * STRIDE;
    int base_w = tx * STRIDE;
    int oc = 0;
    int buf = 0;
    if (oc + OC_TILE <= C_out) {
        for (int widx = tid; widx < weight_tile_elems; widx += num_threads) {
            int j    = widx / (C_IN * KH * KW);
            int rem  = widx % (C_IN * KH * KW);
            int c    = rem / (KH * KW);
            int rem2 = rem % (KH * KW);
            int kh   = rem2 / KW;
            int kw   = rem2 % KW;
            sWeight(buf, widx) = gWeight(oc + j, c, kh, kw);
        }
    }
    __syncthreads();
    for (; oc + OC_TILE <= C_out; oc += OC_TILE) {
        int next_oc = oc + OC_TILE;
        int next_buf = buf ^ 1;
        if (next_oc + OC_TILE <= C_out) {
            for (int widx = tid; widx < weight_tile_elems; widx += num_threads) {
                int j    = widx / (C_IN * KH * KW);
                int rem  = widx % (C_IN * KH * KW);
                int c    = rem / (KH * KW);
                int rem2 = rem % (KH * KW);
                int kh   = rem2 / KW;
                int kw   = rem2 % KW;
                sWeight(next_buf, widx) = gWeight(next_oc + j, c, kh, kw);
            }
        }
        if (valid) {
            float acc[OC_TILE];
            #pragma unroll
            for (int j = 0; j < OC_TILE; ++j) acc[j] = bias[oc + j];
            #pragma unroll
            for (int c = 0; c < C_IN; ++c) {
                #pragma unroll
                for (int kh = 0; kh < KH; ++kh) {
                    #pragma unroll
                    for (int kw = 0; kw < KW; ++kw) {
                        float sval = sInput(c, base_h + kh, base_w + kw);
                        #pragma unroll
                        for (int j = 0; j < OC_TILE; ++j) {
                            int widx2 = ((j * C_IN + c) * KH + kh) * KW + kw;
                            acc[j] += sval * sWeight(buf, widx2);
                        }
                    }
                }
            }
            #pragma unroll
            for (int j = 0; j < OC_TILE; ++j) {
                gOutput(n, oc + j, oh, ow) = acc[j];
            }
        }
        __syncthreads();
        buf = next_buf;
    }
    if (valid) {
        for (; oc < C_out; ++oc) {
            float acc = bias[oc];
            #pragma unroll
            for (int c = 0; c < C_IN; ++c) {
                #pragma unroll
                for (int kh = 0; kh < KH; ++kh) {
                    #pragma unroll
                    for (int kw = 0; kw < KW; ++kw) {
                        acc += sInput(c, base_h + kh, base_w + kw) * gWeight(oc, c, kh, kw);
                    }
                }
            }
            gOutput(n, oc, oh, ow) = acc;
        }
    }
}

torch::Tensor cute_conv2d(torch::Tensor input, torch::Tensor weight, torch::Tensor bias,
                           int64_t stride, int64_t padding) {
    TORCH_CHECK(input.is_cuda() && weight.is_cuda() && bias.is_cuda(), "tensors must be CUDA");
    TORCH_CHECK(input.dim() == 4, "input must be 4D (N,C,H,W)");
    TORCH_CHECK(input.scalar_type() == at::kFloat, "expect float32");
    TORCH_CHECK((int)stride == STRIDE && (int)padding == PAD, "stride/padding mismatch with compiled kernel");
    TORCH_CHECK((int)input.size(1) == C_IN, "in_channels mismatch");
    TORCH_CHECK((int)weight.size(2) == KH && (int)weight.size(3) == KW, "kernel size mismatch");

    auto input_c  = input.contiguous();
    auto weight_c = weight.contiguous();
    auto bias_c   = bias.contiguous();

    int N = (int)input_c.size(0);
    int H = (int)input_c.size(2);
    int W = (int)input_c.size(3);
    int C_out = (int)weight_c.size(0);

    int H_out = (H + 2 * PAD - KH) / STRIDE + 1;
    int W_out = (W + 2 * PAD - KW) / STRIDE + 1;

    auto output = torch::empty({N, C_out, H_out, W_out}, input_c.options());
    dim3 block(TILE, TILE, 1);
    dim3 grid((W_out + TILE - 1) / TILE, (H_out + TILE - 1) / TILE, N);
    constexpr int total_load = C_IN * IN_TILE * IN_TILE;
    constexpr int weight_tile_elems = OC_TILE * C_IN * KH * KW;
    size_t smem_bytes = (size_t)(total_load + 2 * weight_tile_elems) * sizeof(float);
    cudaFuncSetAttribute(cute_conv2d_kernel,
                          cudaFuncAttributeMaxDynamicSharedMemorySize,
                          (int)smem_bytes);
    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    cute_conv2d_kernel<<<grid, block, smem_bytes, stream>>>(
        input_c.data_ptr<float>(),
        weight_c.data_ptr<float>(),
        bias_c.data_ptr<float>(),
        output.data_ptr<float>(),
        N, H, W, C_out, H_out, W_out);
    TORCH_CHECK(cudaGetLastError() == cudaSuccess, "CUTE conv2d launch failed");
    return output;
}
"""

cute_ext = load_inline(
    name="cute_conv2d_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_conv2d"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/workspace/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super(ModelNew, self).__init__()
        # Reuse nn.Conv2d purely as a parameter container to match reference init.
        self.conv1 = nn.Conv2d(in_channels=3, out_channels=96, kernel_size=11, stride=4, padding=2)
        self._ext = cute_ext

    def forward(self, x):
        x = x.contiguous().cuda().float()
        weight = self.conv1.weight
        bias = self.conv1.bias
        return self._ext.cute_conv2d(x, weight, bias, 4, 2)

